using System;class Program{static void Main(){int a=-1;long b=-1L;nint c=(nint)(-1);Console.WriteLine(a>>>1);Console.WriteLine(b>>>65);Console.WriteLine((long)(c>>>1));a>>>=1;Console.WriteLine(a);int amount=300;try{Console.WriteLine(checked((byte)amount));}catch(Exception error){Console.WriteLine(error.GetType().Name);}long maximum=long.MaxValue;try{Console.WriteLine(checked(maximum+1L));}catch(Exception error){Console.WriteLine(error.GetType().Name);}}}